def test_native_author_reference_provenance_and_fixed_inputs():
    assert REFERENCE["status"] == "passed"
    assert REFERENCE["KFAS"] == "1.6.0"
    assert REFERENCE["R"].startswith("R version 4.6.1 ")
    assert REFERENCE["license"] == "GPL (>= 2)"
    assert REFERENCE["source_package"].endswith("66aab472a9d29c08c52a8ebcd3da531c9daadba3")
    assert hashlib.sha256(REFERENCE["setup_code"].encode()).hexdigest() == REFERENCE["setup_sha256"]
    payload = json.dumps(REFERENCE["inputs"], sort_keys=True, separators=(",", ":"))
    assert hashlib.sha256(payload.encode()).hexdigest() == REFERENCE["input_sha256"]
    assert "transform='augment'" in REFERENCE["setup_code"]
    assert "identical(unname(model$P1inf),unname(P1inf))" in REFERENCE["setup_code"]
    for key in ("binary_sha256", "rscript_sha256"):
        assert len(REFERENCE[key]) == 64
        int(REFERENCE[key], 16)


@pytest.mark.parametrize("case,author", list(zip(REFERENCE["inputs"], REFERENCE["cases"], strict=True)),
                         ids=[case["name"] for case in REFERENCE["inputs"]])
def test_full_fixed_system_moments_against_actual_native_kfas(case, author):
    def array(record):
        shape = record["shape"] if isinstance(record["shape"], list) else [record["shape"]]
        return np.array(record["values"], dtype=float).reshape(shape, order="F")
    y = torch.tensor([[float("nan") if v is None else v for v in row] for row in case["y"]], dtype=torch.float64)
    values = {k: torch.tensor(v, dtype=torch.float64) for k, v in case["system"].items()}
    actual = smooth_exact_diffuse(y, values)
    n, p, m = len(y), y.shape[1], len(values["a0"])
    moments = author["moments"]
    augmented = array(moments["alphahat"]).shape[1] > m+1
    pairs = {"smoothed": array(moments["alphahat"])[:, :m],
             "smoothed_covariance": array(moments["V"])[:m, :m].transpose(2, 0, 1),
             "filtered": array(moments["att"])[:, :m],
             "filtered_covariance": array(moments["Ptt"])[:m, :m].transpose(2, 0, 1),
             "prior_mean": array(moments["a"])[:n, :m],
             "prior_covariance": array(moments["P"])[:m, :m, :n].transpose(2, 0, 1),
             "prior_diffuse_covariance": array(moments["Pinf"])[:m, :m, :n].transpose(2, 0, 1),
             "process_disturbance": array(moments["etahat"])[:, :m],
             "process_disturbance_covariance": array(moments["V_eta"])[:m, :m].transpose(2, 0, 1),
             "measurement_disturbance": array(moments["alphahat"])[:, m+1:] if augmented else array(moments["epshat"]).reshape(n, p),
             "measurement_disturbance_covariance": array(moments["V"])[m+1:, m+1:].transpose(2, 0, 1) if augmented else array(moments["V_eps"]).reshape(p, n).T[:, :, None]}
    if augmented:
        pairs["measurement_state_covariance"] = array(moments["V"])[m+1:, :m].transpose(2, 0, 1)
    for name, target in pairs.items():
        if name == "prior_diffuse_covariance" and len(target) < n:
            target = np.concatenate((target, np.zeros((n-len(target), m, m))))
        np.testing.assert_allclose(actual[name].numpy(), target, atol=2e-10, rtol=2e-10, err_msg=case["name"]+":"+name)
    assert float(actual["log_likelihood"]) == pytest.approx(author["logLik"], abs=2e-10, rel=2e-10)
